nversation_members').insert([{'conversation_id':c['id'],'user_id':me.id,'role':'member'},{'conversation_id':c['id'],'user_id':p['id'],'role':'member'}]);if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatPage(id:c['id'],title:p['display_name']??'گفتگو',group:false))).then((_){load();});}catch(e){if(mounted)snack(context,'گفتگو ساخته نشد: $e');}}Future<void> logout()async{await online(false);await supabase.auth.signOut();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const LoginPage()),(_)=>false);} @override void dispose(){q.dispose();online(false);super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Arad Messenger'),actions:[IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const GroupCreatePage())).then((_){load();}),icon:const Icon(Icons.group_add_outlined)),IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const ProfilePage())),icon:const Icon(Icons.person_outline)),IconButton(onPressed:logout,icon:const Icon(Icons.logout))]),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:q,onChanged:search,decoration:const InputDecoration(hintText:'جستجوی کاربر...',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))),if(users.isNotEmpty)Expanded(child:ListView(children:users.map((p)=>ListTile(leading:av(p),title:Text(p['display_name']??''),subtitle:Text('@${p['username']??''}'),onTap:(){q.clear();setState(()=>users=[]);direct(p);})).toList()))else Expanded(child:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:chats.length,itemBuilder:(_,i){final x=chats[i],cc=x['c'] as Map<String,dynamic>,p=x['p'] as Map<String,dynamic>?,last=x['last'] as Map<String,dynamic>?;final isGroup=cc['type']=='group';return ListTile(leading:isGroup?CircleAvatar(child:const Icon(Icons.groups)):av(p),title:Text(isGroup?(cc['title']??'گروه'):(p?['display_name']??'گفتگو')),subtitle:Text(last?['message_type']=='text'?(last?['body']??''): 'فایل':'شروع گفتگو'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatPage(id:cc['id'],title:isGroup?(cc['title']??'گروه'):(p?['display_name']??'گفتگو'),group:isGroup))).then((_){load();}););})))],),floatingActionButton:FloatingActionButton(onPressed:()=>q.requestFocus(),child:const Icon(Icons.chat_rounded)));}
