class _GroupCreatePageState extends State<GroupCreatePage>{final title=TextEditingController(),q=TextEditingController();List<Map<String,dynamic>> found=[];final selected=<Map<String,dynamic>>[];bool busy=false;Future<void> search(String s)async{if(s.trim().length<2){setState(()=>found=[]);return;}try{final r=await supabase.rpc('search_profiles',params:{'search_text':s.trim()});if(mounted)setState(()=>found=List<Map<String,dynamic>>.from(r));}catch(_){} }Future<void> create()async{final me=supabase.auth.currentUser;if(me==null||title.text.trim().length<2||selected.isEmpty)return snack(context,'نام گروه و حداقل یک عضو را انتخاب کنید.');setState(()=>busy=true);try{final c=await supabase.from('conversations').insert({'type':'group','title':title.text.trim(),'created_by':me.id}).select().single();final members=<Map<String,dynamic>>[{'conversation_id':c['id'],'user_id':me.id,'role':'admin'}];members.addAll(selected.map((p)=>{'conversation_id':c['id'],'user_id':p['id'],'role':'member'}));await supabase.from('conversation_members').insert(members);if(mounted)Navigator.pop(context);}catch(e){if(mounted)snack(context,'ساخت گروه ناموفق بود: $e');}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){title.dispose();q.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('ساخت گروه')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:title,decoration:const InputDecoration(labelText:'نام گروه',border:OutlineInputBorder()))),Padding(padding:const EdgeInsets.fromLTRB(12,0,12,8),child:TextField(controller:q,onChanged:search,decoration:const InputDecoration(hintText:'افزودن اعضا...',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))),if(selected.isNotEmpty)SizedBox(height:70,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(8),children:selected.map((p)=>Padding(padding:const EdgeInsets.only(right:8),child:Chip(label:Text(p['display_name']??''),onDeleted:()=>setState(()=>selected.remove(p)))).toList())),Expanded(child:ListView(children:found.map((p)=>ListTile(leading:av(p),title:Text(p['display_name']??''),subtitle:Text('@${p['username']??''}'),trailing:selected.any((x)=>x['id']==p['id'])?const Icon(Icons.check_circle):const Icon(Icons.add),onTap:(){if(selected.any((x)=>x['id']==p['id'])){setState(()=>selected.removeWhere((x)=>x['id']==p['id']));}else{setState(()=>selected.add(p));}})).toList())),Padding(padding:const EdgeInsets.all(12),child:SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:create,child:Text(busy?'در حال ساخت...':'ساخت گروه'))))]));}
