class ChatPage extends StatefulWidget{final String id,title;final bool group;const ChatPage({super.key,required this.id,required this.title,required this.group});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final text=TextEditingController();final scroll=ScrollController();final picker=ImagePicker();final recorder=AudioRecorder();List<Map<String,dynamic>> messages=[];Map<String,List<Map<String,dynamic>>> attachments={};RealtimeChannel? channel;bool loading=true,sending=false,recording=false;String? replyId;@override void initState(){super.initState();load();channel=supabase.channel('chat-${widget.id}').onPostgresChanges(event:PostgresChangeEvent.all,schema:'public',table:'messages',filter:PostgresChangeFilter(type:PostgresChangeFilterType.eq,column:'conversation_id',value:widget.id),callback:(_)=>load()).subscribe();}
Future<void> load()async{try{final r=await supabase.from('messages').select().eq('conversation_id',widget.id).order('created_at');final list=List<Map<String,dynamic>>.from(r);final a=<String,List<Map<String,dynamic>>>{};for(final m in list){final ar=await supabase.from('message_attachments').select().eq('message_id',m['id']);final aa=<Map<String,dynamic>>[];for(final x in ar){final path=x['storage_path'];try{final url=await supabase.storage.from('chat-media').createSignedUrl(path,3600);aa.add({...Map<String,dynamic>.from(x),'url':url});}catch(_){}}a[m['id']]=aa;}if(mounted)setState((){messages=list;attachments=a;});await markRead();WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.jumpTo(scroll.position.maxScrollExtent);});}catch(e){if(mounted)snack(context,'خطا در پیام‌ها: $e');}finally{if(mounted)setState(()=>loading=false);}}
Future<void> markRead()async{final me=supabase.auth.currentUser?.id;if(me==null)return;try{await supabase.from('messages').update({'read_at':DateTime.now().toIso8601String()}).eq('conversation_id',widget.id).neq('sender_id',me).isFilter('read_at',null);}catch(_){} }
Future<void> sendText()async{final body=text.text.trim();final me=supabase.auth.currentUser;if(me==null||body.isEmpty||sending)return;setState(()=>sending=true);text.clear();try{final r=await supabase.from('messages').insert({'conversation_id':widget.id,'sender_id':me.id,'body':body,'message_type':'text','reply_to':replyId}).select().single();await supabase.from('messages').update({'delivered_at':DateTime.now().toIso8601String()}).eq('id',r['id']);replyId=null;await load();}catch(e){if(mounted)snack(context,'ارسال نشد: $e');}finally{if(mounted)setState(()=>sending=false);}}
Future<void> sendFiles()async{final me=supabase.auth.currentUser;if(me==null)return;final result=await FilePicker.platform.pickFiles(allowMultiple:true,type:FileType.any,withData:false);if(result==null)return;for(final f in result.files){if(f.path==null)continue;await uploadBytes(File(f.path!).readAsBytes(),f.name,f.extension==null?'application/octet-stream':_mime(f.extension!),'file');}}
String _mime(String e){final x=e.toLowerCase();if(['jpg','jpeg','png','gif','webp'].contains(x))return'image/$x';if(['mp4','mov','mkv','webm'].contains(x))return'video/$x';if(['mp3','m4a','aac','wav','ogg'].contains(x))return'audio/$x';return'application/octet-stream';}
Future<void> pickMedia(bool video)async{final x=video?await picker.pickVideo(source:ImageSource.gallery):await picker.pickImage(source:ImageSource.gallery);if(x==null)return;await uploadBytes(await x.readAsBytes(),x.name,x.mimeType??(video?'video/mp4':'image/jpeg'),video?'video':'image');}
Future<void> uploadBytes(Future<List<int>> bytes,String name,String mime,String type)async{final me=supabase.auth.currentUser;if(me==null)return;final data=await bytes;final path='${widget.id}/${DateTime.now().millisecondsSinceEpoch}_$name';try{await supabase.storage.from('chat-media').uploadBinary(path,data,fileOptions:FileOptions(contentType:mime,upsert:false));final m=await supabase.from('messages').insert({'conversation_id':widget.id,'sender_id':me.id,'body':name,'message_type':type,'reply_to':replyId}).select().single();await supabase.from('message_attachments').insert({'message_id':m['id'],'storage_path':path,'file_name':name,'mime_type':mime,'file_size':data.length});replyId=null;await load();}catch(e){if(mounted)snack(context,'آپلود انجام نشد: $e');}}
Future<void> voice()async{final me=supabase.auth.currentUser;if(me==null)return;if(recording){final path=await recorder.stop();setState(()=>recording=false);if(path!=null)await uploadBytes(File(path).readAsBytes(),'voice_${DateTime.now().millisecondsSinceEpoch}.m4a','audio/mp4','audio');return;}if(!await recorder.hasPermission()){if(mounted)snack(context,'دسترسی میکروفون لازم است.');return;}final dir=Directory.systemTemp.path;final path='$dir/arad_${DateTime.now().millisecondsSinceEpoch}.m4a';await recorder.start(const RecordConfig(encoder:AudioEncoder.aacLc),path:path);setState(()=>recording=true);}
Future<void> react(Map<String,dynamic> m)async{final me=supabase.auth.currentUser;if(me==null)return;try{await supabase.from('message_reactions').upsert({'message_id':m['id'],'user_id':me.id,'reaction':'❤️'});if(mounted)snack(context,'واکنش اضافه شد ❤️');}catch(e){if(mounted)snack(context,'واکنش ناموفق بود: $e');}}
Future<void> edit(Map<String,dynamic> m)async{if(m['sender_id']!=supabase.auth.currentUser?.id)return;final c=TextEditingController(text:m['body']??'');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('ویرایش پیام'),content:TextField(controller:c,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('ذخیره'))]));if(ok==true&&c.text.trim().isNotEmpty){await supabase.from('messages').update({'body':c.text.trim(),'edited_at':DateTime.now().toIso8601String()}).eq('id',m['id']);await load();}}
Future<void> deleteMsg(Map<String,dynamic> m)async{if(m['sender_id']!=supabase.auth.currentUser?.id)return;await supabase.from('messages').update({'body':'این پیام حذف شد','deleted_at':DateTime.now().toIso8601String()}).eq('id',m['id']);await load();}
