Widget bubble(Map<String,dynamic> m,bool mine){final at=attachments[m['id']]??[];return GestureDetector(onLongPress:()=>showModalBottomSheet(context:context,builder:(_)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.reply),title:const Text('پاسخ'),onTap:(){Navigator.pop(context);setState(()=>replyId=m['id']);}),ListTile(leading:const Icon(Icons.favorite),title:const Text('واکنش ❤️'),onTap:(){Navigator.pop(context);react(m);}),if(mine&&m['message_type']=='text')ListTile(leading:const Icon(Icons.edit),title:const Text('ویرایش'),onTap:(){Navigator.pop(context);edit(m);}),if(mine)ListTile(leading:const Icon(Icons.delete_outline),title:const Text('حذف'),onTap:(){Navigator.pop(context);deleteMsg(m);})]))),child:Container(margin:const EdgeInsets.symmetric(vertical:4),padding:const EdgeInsets.all(10),constraints:const BoxConstraints(maxWidth:330),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[if(m['reply_to']!=null)const Align(alignment:Alignment.centerLeft,child:Text('↩ پاسخ به پیام',style:TextStyle(fontSize:11))),if(at.isNotEmpty)...at.map((a)=>Padding(padding:const EdgeInsets.only(bottom:6),child:a['mime_type'].toString().startsWith('image/')?ClipRRect(borderRadius:BorderRadius.circular(12),child:Image.network(a['url'],height:180,width:240,fit:BoxFit.cover)):Row(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.insert_drive_file),const SizedBox(width:6),Flexible(child:Text(a['file_name']??'فایل'))]))),if(m['message_type']=='text')Text(m['body']??''),if(m['message_type']=='audio')const Row(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.mic),Text(' پیام صوتی')]),if(m['edited_at']!=null)const Text(' ویرایش‌شده',style:TextStyle(fontSize:10)),if(mine)Text(m['read_at']!=null?'✓✓':m['delivered_at']!=null?'✓':'○',style:const TextStyle(fontSize:11))]));}
