class ProfilePage extends StatefulWidget{const ProfilePage({super.key});@override State<ProfilePage> createState()=>_ProfilePageState();}
class _ProfilePageState extends State<ProfilePage>{final n=TextEditingController(),u=TextEditingController(),b=TextEditingController();String? avatar;bool busy=false;@override void initState(){super.initState();load();}Future<void> load()async{final me=supabase.auth.currentUser;if(me==null)return;final p=await supabase.from('profiles').select().eq('id',me.id).maybeSingle();if(p!=null&&mounted)setState((){n.text=p['display_name']??'';u.text=p['username']??'';b.text=p['bio']??'';avatar=p['avatar_url'];});}Future<void> photo()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:85);if(x==null)return;final path='${supabase.auth.currentUser!.id}/${DateTime.now().millisecondsSinceEpoch}.jpg';try{await supabase.storage.from('avatars').uploadBinary(path,await x.readAsBytes(),fileOptions:const FileOptions(contentType:'image/jpeg',upsert:true));final url=supabase.storage.from('avatars').getPublicUrl(path);await supabase.from('profiles').update({'avatar_url':url}).eq('id',supabase.auth.currentUser!.id);if(mounted)setState(()=>avatar=url);}catch(e){if(mounted)snack(context,'آپلود عکس ناموفق بود: $e');}}Future<void> save()async{final me=supabase.auth.currentUser;if(me==null)return;setState(()=>busy=true);try{await supabase.from('profiles').update({'display_name':n.text.trim(),'username':u.text.trim().toLowerCase(),'bio':b.text.trim()}).eq('id',me.id);if(mounted)Navigator.pop(context);}catch(e){if(mounted)snack(context,'ذخیره نشد: $e');}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){n.dispose();u.dispose();b.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('پروفایل')),body:ListView(padding:const EdgeInsets.all(24),children:[Center(child:GestureDetector(onTap:photo,child:CircleAvatar(radius:52,backgroundImage:avatar!=null?NetworkImage(avatar!):null,child:avatar==null?const Icon(Icons.person,size:50):null))),const SizedBox(height:24),TextField(controller:n,decoration:const InputDecoration(labelText:'نام',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:u,decoration:const InputDecoration(labelText:'نام کاربری',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:b,maxLines:3,decoration:const InputDecoration(labelText:'بیو',border:OutlineInputBorder())),const SizedBox(height:18),FilledButton(onPressed:busy?null:save,child:Text(busy?'...':'ذخیره'))]));}
